//
// Package excelize providing a set of functions that allow you to write to and
// read from XLAM / XLSM / XLSX / XLTM / XLTX files. Supports reading and
// writing spreadsheet documents generated by Microsoft Excel™ 2007 and later.
// Supports complex components by high compatibility, and provided streaming
// API for generating or reading data from a worksheet with huge amounts of
// data. This library needs Go version 1.26.0 or later.

package excelize

//go:generate go tool -modfile=go.tools.mod goverter gen .

// worksheetCloner defines the deep copy methods generated by goverter.
//
// goverter:converter
// goverter:output:file ./worksheet_cloner_gen.go
// goverter:output:package :excelize
// goverter:name worksheetClonerImpl
type worksheetCloner interface {
	// goverter:ignore mu formulaSI
	cloneWorksheet(source *xlsxWorksheet) *xlsxWorksheet
	cloneCol(source xlsxCol) xlsxCol
	cloneRow(source xlsxRow) xlsxRow
	cloneConditionalFormatting(source xlsxConditionalFormatting) xlsxConditionalFormatting
	cloneDataValidation(source xlsxDataValidation) xlsxDataValidation
}

// cloner is initialized outside the goverter build so generation
// can load the package without the generated implementation.
var cloner worksheetCloner
